import{_ as h,C as c,o,c as p,j as t,a,b as l,w as r,E as s,a8 as d,a9 as i}from"./chunks/framework.BOiBTRPC.js";const A=JSON.parse('{"title":"Designing Reliable Pipelines","description":"The reference architecture and the reliability patterns — idempotency, backpressure, DLQs, schema contracts, fault tolerance, data SLOs — plus a worked capacity estimation.","frontmatter":{"title":"Designing Reliable Pipelines","description":"The reference architecture and the reliability patterns — idempotency, backpressure, DLQs, schema contracts, fault tolerance, data SLOs — plus a worked capacity estimation."},"headers":[],"relativePath":"system-design/pipeline-design.md","filePath":"system-design/pipeline-design.md"}'),m={name:"system-design/pipeline-design.md"};function g(b,e,f,y,k,w){const n=c("Mermaid"),u=c("QuizCard");return o(),p("div",null,[e[3]||(e[3]=t("h1",{id:"designing-reliable-pipelines",tabindex:"-1"},[a("Designing Reliable Pipelines "),t("a",{class:"header-anchor",href:"#designing-reliable-pipelines","aria-label":'Permalink to "Designing Reliable Pipelines"'},"​")],-1)),e[4]||(e[4]=t("blockquote",null,[t("p",null,[t("strong",null,"Why it matters"),a(" — Pipelines don't fail at design review; they fail at 3am on a retry, a schema change, or a source that silently doubled its volume. This chapter is the checklist of patterns that keep a pipeline correct "),t("em",null,"under failure"),a(" — which is the only time correctness is tested.")])],-1)),e[5]||(e[5]=t("h2",{id:"the-reference-architecture",tabindex:"-1"},[a("The reference architecture "),t("a",{class:"header-anchor",href:"#the-reference-architecture","aria-label":'Permalink to "The reference architecture"'},"​")],-1)),(o(),l(d,null,{default:r(()=>[s(n,{id:"mermaid-11",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Sources%5B%22Sources%22%5D%0A%20%20%20%20%20%20%20%20S1%5B%22OLTP%20%2F%20CDC%22%5D%0A%20%20%20%20%20%20%20%20S2%5B%22Event%20streams%22%5D%0A%20%20%20%20%20%20%20%20S3%5B%22Files%20%2F%20APIs%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Lake%5B%22Storage%20layers%22%5D%0A%20%20%20%20%20%20%20%20R%5B%22Raw%20%E2%80%94%20immutable%20landing%2C%20append-only%22%5D%20--%3E%20C%5B%22Curated%20%E2%80%94%20deduped%2C%20conformed%2C%20modeled%22%5D%20--%3E%20V%5B%22Serve%20%E2%80%94%20marts%2C%20aggregates%2C%20feature%20tables%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Obs%5B%22Observability%20plane%20%E2%80%94%20every%20layer%20emits%22%5D%0A%20%20%20%20%20%20%20%20O1%5B%22Metrics%3A%20lag%2C%20throughput%2C%20freshness%22%5D%0A%20%20%20%20%20%20%20%20O2%5B%22Lineage%20and%20schema%20registry%22%5D%0A%20%20%20%20%20%20%20%20O3%5B%22Data%20quality%20checks%22%5D%0A%20%20%20%20%20%20%20%20O4%5B%22DLQ%20and%20alerting%22%5D%0A%20%20%20%20end%0A%20%20%20%20S1%20--%3E%7C%22CDC%20%2F%20producers%20%2F%20batch%20pulls%22%7C%20R%0A%20%20%20%20S2%20--%3E%7C%22CDC%20%2F%20producers%20%2F%20batch%20pulls%22%7C%20R%0A%20%20%20%20S3%20--%3E%7C%22CDC%20%2F%20producers%20%2F%20batch%20pulls%22%7C%20R%0A%20%20%20%20R%20-.-%3E%20O1%0A%20%20%20%20R%20-.-%3E%20O4%0A%20%20%20%20C%20-.-%3E%20O1%0A%20%20%20%20C%20-.-%3E%20O3%0A%20%20%20%20C%20-.-%3E%20O4%0A%20%20%20%20V%20-.-%3E%20O1%0A%20%20%20%20V%20-.-%3E%20O2%0A%20%20%20%20V%20--%3E%20Consumers%5B%22BI%20%C2%B7%20APIs%20%C2%B7%20ML%20features%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p>Design rules encoded in that diagram:</p><ul><li><strong>Raw is immutable and replayable.</strong> Never transform into raw — land bytes/events as received, partitioned by arrival time. Every downstream bug is fixable by replaying raw.</li><li><strong>Each layer is a checkpoint.</strong> Raw→curated→serve are separate, independently re-runnable jobs. Don&#39;t build one monolith job spanning all three.</li><li><strong>The observability plane is a peer, not an afterthought.</strong> Every layer emits freshness, volume, schema, and lineage metadata or the pipeline is a black box the first time it lies.</li><li><strong>Schemas are enforced at the boundary, not in the middle.</strong> Validate at ingest into curated; a bad record dies at raw→curated, never propagates to serve.</li><li><strong>Every hop is observable.</strong> If you can&#39;t answer &quot;is this partition complete and fresh?&quot; per layer, the pipeline isn&#39;t done — it&#39;s just running.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The most common architecture smell in reviews: transformations fused across layers (raw→serve in one job) to &quot;save a step.&quot; You lose independent reprocessing and blame attribution — the two things you need most during an incident.</p></div><h2 id="idempotency-making-retries-safe" tabindex="-1">Idempotency: making retries safe <a class="header-anchor" href="#idempotency-making-retries-safe" aria-label="Permalink to &quot;Idempotency: making retries safe&quot;">​</a></h2><p>Networks retry. Frameworks retry. Humans click &quot;rerun.&quot; If your write isn&#39;t idempotent, every one of those is a duplicate.</p><table tabindex="0"><thead><tr><th>Technique</th><th>Mechanism</th><th>Scope</th><th>Gotcha</th></tr></thead><tbody><tr><td><strong>Idempotency key</strong></td><td>Client-supplies unique key per logical op; sink dedupes on it</td><td>API/event ingestion</td><td>Key must survive across retries — derive from content, not <code>uuid4()</code> per attempt</td></tr><tr><td><strong>Natural/business key upsert</strong></td><td><code>MERGE</code>/<code>INSERT ... ON CONFLICT</code> on <code>order_id</code>, <code>event_id</code></td><td>DB sinks</td><td>Requires true natural key; composite keys on NULLs silently don&#39;t dedupe</td></tr><tr><td><strong>Dedupe window</strong></td><td>Remember seen keys for T (bloom filter, KV store, table partition)</td><td>Streams</td><td>Window too short → duplicates on late retry; too long → storage/memory cost</td></tr><tr><td><strong>Deterministic output</strong></td><td>Rerun produces byte-identical output; write via partition overwrite</td><td>Batch</td><td>The strongest guarantee — rerun <em>is</em> the dedupe</td></tr></tbody></table>',6)),(o(),l(d,null,{default:r(()=>[s(n,{id:"mermaid-129",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20P%20as%20Producer%0A%20%20%20%20participant%20W%20as%20Ingestion%20writer%0A%20%20%20%20participant%20T%20as%20Target%20table%0A%20%20%20%20P-%3E%3EW%3A%20event%20e42%20with%20idem-key%20hash%20of%20order_id%2C%20type%2C%20ts%0A%20%20%20%20W-%3E%3ET%3A%20INSERT%20ON%20CONFLICT%20idem_key%20DO%20NOTHING%0A%20%20%20%20Note%20over%20W%3A%20timeout%20%E2%80%94%20was%20it%20written%3F%0A%20%20%20%20P-%3E%3EW%3A%20RETRY%20same%20idem-key%0A%20%20%20%20W-%3E%3ET%3A%20INSERT%20ON%20CONFLICT%20becomes%20a%20no-op%0A%20%20%20%20T--%3E%3EP%3A%20200%20%E2%80%94%20one%20row%20total%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=i('<div class="info custom-block"><p class="custom-block-title">ℹ️</p><p>Partition-level idempotency is the batch version: write to a staging partition, then <code>INSERT OVERWRITE</code> the target partition. A rerun overwrites the same partition — the <em>output path</em> is the idempotency key.</p></div><h2 id="the-exactly-once-illusion" tabindex="-1">The exactly-once illusion <a class="header-anchor" href="#the-exactly-once-illusion" aria-label="Permalink to &quot;The exactly-once illusion&quot;">​</a></h2><p><strong>Exactly-once delivery does not exist.</strong> The Two Generals&#39; Problem: no protocol guarantees a message is both delivered and acknowledged over an unreliable network. What exists:</p><ul><li><strong>At-most-once</strong>: send, don&#39;t retry → may lose data.</li><li><strong>At-least-once</strong>: retry until acked → may duplicate.</li><li><strong>Effectively once</strong> (what people mean): at-least-once transport + <strong>idempotent processing + dedupe at the sink</strong>. The system <em>can</em> process a record twice; it just can&#39;t <em>observe</em> the effect twice.</li></ul><p>Framework &quot;exactly-once&quot; (Kafka EOS, Flink checkpointing) scopes this to <em>inside the framework</em> — read-process-write within Kafka/Flink state. The moment your sink is an external system (warehouse, API), you&#39;re back to at-least-once + idempotency unless the sink participates in the framework&#39;s transaction.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Risk / production failure mode</p><p>&quot;Exactly-once&quot; marketing causes real outages: engineers disable dedupe because &quot;Flink guarantees it,&quot; then a sink-side retry (outside the checkpoint boundary) double-writes revenue events. Guarantee boundaries: exactly-once ends at the last framework-managed write.</p></div><details class="details custom-block"><summary>Sizing the dedupe window — the underrated parameter</summary><p>Dedupe state must cover your <em>worst-case redelivery horizon</em>, not the common one. Sources of late redelivery: consumer restart/replay (your longest realistic backfill), producer-side retries (hours on mobile/edge sources), and stream reprocessing after a bug fix (days). Rule of thumb: window ≥ max(retention of upstream retries, longest planned reprocessing horizon). Storage math is cheap: 50k events/s × 32-byte key × 24h ≈ 138 GB — feasible in Redis or a compacted Kafka topic; 7 days ≈ 1 TB — move to a bloom filter (with stated false-positive tolerance) or a partitioned dedupe table. A bloom filter trades: no exact lookups, tiny memory, but ~1% false &quot;duplicate&quot; verdicts — acceptable for metrics, unacceptable for payments.</p></details><h2 id="backpressure-and-load-shedding" tabindex="-1">Backpressure and load shedding <a class="header-anchor" href="#backpressure-and-load-shedding" aria-label="Permalink to &quot;Backpressure and load shedding&quot;">​</a></h2><p>When consumers fall behind, something has to give. Choose consciously:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Behavior</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Backpressure (pull)</strong></td><td>Consumer reads at its own rate; producer blocks/buffers</td><td>Durable buffer exists (Kafka, queue) — preferred default</td></tr><tr><td><strong>Bounded buffer + drop</strong></td><td>Buffer to capacity, then drop oldest/newest</td><td>Metrics, telemetry where loss &gt; lag</td></tr><tr><td><strong>Load shedding</strong></td><td>Reject requests at the edge (429/503)</td><td>Interactive systems where latency SLO matters more than completeness</td></tr><tr><td><strong>Autoscale</strong></td><td>Add consumers on lag</td><td>Works until downstream (warehouse, API) becomes the bottleneck</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The durable log <em>is</em> your backpressure strategy. Kafka retaining 7 days means a 6-hour consumer outage is a lag problem, not a data-loss problem. Backpressure becomes data loss only when lag exceeds retention.</p></div><h3 id="retry-policy-primer" tabindex="-1">Retry policy primer <a class="header-anchor" href="#retry-policy-primer" aria-label="Permalink to &quot;Retry policy primer&quot;">​</a></h3><p>Retries are the default response to transient failure — and the default <em>cause</em> of cascading failure when done naively:</p><ul><li><strong>Exponential backoff with jitter</strong>: <code>delay = base × 2^attempt</code>, randomized ±50%. Without jitter, synchronized clients retry in lockstep — the &quot;thundering herd&quot; that keeps a recovering service down.</li><li><strong>Retry budgets</strong>: cap retries as a fraction of total requests (e.g., ≤10%), not just per-request attempts. A client retrying 3× under a full outage triples load on a dying dependency.</li><li><strong>Retry only transient errors</strong>: 429/503/timeouts → retry; 4xx/validation/schema errors → fail fast to DLQ. Retrying a poison record wastes your budget and delays detection.</li><li><strong>Deadline &gt; per-attempt timeout</strong>: bound the <em>whole</em> operation (including retries), or tail latency explodes.</li></ul><h2 id="dead-letter-queues" tabindex="-1">Dead-letter queues <a class="header-anchor" href="#dead-letter-queues" aria-label="Permalink to &quot;Dead-letter queues&quot;">​</a></h2><p>A DLQ holds records that can&#39;t be processed — poison pills, schema violations, downstream hard-failures. Design decisions that matter:</p><ul><li><strong>Wrap the record, don&#39;t just drop it.</strong> DLQ entry = original payload + failure metadata (error, stack, attempt count, source offset). You will need all of it to replay.</li><li><strong>DLQ volume is a first-class metric.</strong> Alert on it. A pipeline &quot;succeeding&quot; while its DLQ fills is silently losing data.</li><li><strong>Have a replay path.</strong> Re-drive DLQ records after fix — same consumer with a flag, or a dedicated replayer. A DLQ you can&#39;t replay is a trash can.</li><li><strong>Bound retries first.</strong> Retry transient failures (with exponential backoff + jitter) N times <em>before</em> DLQing — most &quot;poison&quot; records are just unlucky.</li></ul>',17)),(o(),l(d,null,{default:r(()=>[s(n,{id:"mermaid-299",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20I%5B%22Input%20record%22%5D%20--%3E%20P%5B%22Process%22%5D%0A%20%20%20%20P%20--%3E%7C%22ok%22%7C%20S%5B%22Sink%22%5D%0A%20%20%20%20P%20--%3E%7C%22transient%20error%2C%20attempt%20%3C%20N%22%7C%20B%5B%22Backoff%20%2B%20jitter%22%5D%20--%3E%20P%0A%20%20%20%20P%20--%3E%7C%22exhausted%20or%20permanent%22%7C%20D%5B%22DLQ%3A%20payload%20%2B%20error%20%2B%20offset%22%5D%0A%20%20%20%20D%20-.-%3E%7C%22after%20fix%3A%20replay%22%7C%20P%0A%20%20%20%20D%20--%3E%20A%5B%22Alert%20on%20volume%22%5D%0A"})]),fallback:r(()=>[...e[2]||(e[2]=[a(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=i('<h2 id="schema-evolution-and-data-contracts" tabindex="-1">Schema evolution and data contracts <a class="header-anchor" href="#schema-evolution-and-data-contracts" aria-label="Permalink to &quot;Schema evolution and data contracts&quot;">​</a></h2><p>Producers and consumers evolve independently. Compatibility defines who can upgrade first without breaking the other (Avro semantics; Protobuf/JSON Schema similar):</p><table tabindex="0"><thead><tr><th>Change</th><th>Backward (new reads old)</th><th>Forward (old reads new)</th><th>Full</th></tr></thead><tbody><tr><td>Add field <strong>with default</strong></td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Add field <strong>no default</strong></td><td>❌</td><td>✅</td><td>❌</td></tr><tr><td>Remove field <strong>with default</strong></td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Remove field <strong>no default</strong></td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>Change type</td><td>❌ (unless promotable, e.g. int→long)</td><td>❌</td><td>❌</td></tr><tr><td>Rename field</td><td>❌ (alias can save it)</td><td>❌</td><td>❌</td></tr></tbody></table><ul><li><strong>Backward</strong> (most common default): upgrade consumers first, then producers.</li><li><strong>Forward</strong>: upgrade producers first.</li><li><strong>Full</strong>: upgrade in any order — the safest contract.</li></ul><div class="info custom-block"><p class="custom-block-title">ℹ️</p><p>The universal rule that falls out of the table: <strong>only ever add optional fields with defaults, and never remove or rename.</strong> That alone is full-compatible. Everything else requires coordination.</p></div><p><strong>Data contracts</strong> formalize this: schema + semantics + SLOs agreed between producer and consumer, enforced in CI (schema registry compatibility check) and at ingest (contract validation → DLQ on violation). A contract that isn&#39;t enforced at the boundary is documentation, not a contract.</p><p>Contract scope checklist — what a real contract pins down beyond the schema: required fields and nullability, enum/allowed-value sets, key uniqueness and dedupe semantics, freshness and volume expectations, and the escalation path when violated. Schema alone catches shape breaks; semantics catch &quot;shape fine, meaning changed&quot; — the harder failure.</p><h2 id="fault-tolerance-patterns" tabindex="-1">Fault-tolerance patterns <a class="header-anchor" href="#fault-tolerance-patterns" aria-label="Permalink to &quot;Fault-tolerance patterns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Mechanism</th><th>Recovery semantic</th></tr></thead><tbody><tr><td><strong>Checkpoint + restart</strong></td><td>Persist progress (offsets, state snapshots); resume from last checkpoint</td><td>At-least-once replay from checkpoint → needs idempotent sink</td></tr><tr><td><strong>Lineage replay</strong></td><td>Recompute from immutable raw/inputs</td><td>Deterministic — the strongest recovery, but only if inputs are replayable</td></tr><tr><td><strong>Write-ahead log</strong></td><td>Log intent before mutating state</td><td>Crash → replay WAL to reconstruct state</td></tr><tr><td><strong>Blue-green backfill</strong></td><td>Build corrected table/partition alongside; atomic swap</td><td>Zero-downtime correction; no partial-state exposure</td></tr><tr><td><strong>Transactional outbox</strong></td><td>Write intent to an outbox table in same TX as state; relay publishes it</td><td>Atomicity between DB write and message send</td></tr></tbody></table><details class="details custom-block"><summary>The outbox pattern is the one worth memorizing</summary><p>The dual-write problem: &quot;update the DB, then publish the event&quot; is non-atomic — crash between them and they diverge forever. Outbox: write the event row inside the same DB transaction; a separate relay (CDC on the outbox table) publishes it. Now the DB is the single atomic commit point and the event can&#39;t be lost or half-sent. This is how Debezium-based CDC architectures guarantee consistency between the row and the event.</p></details><h2 id="slos-for-data" tabindex="-1">SLOs for data <a class="header-anchor" href="#slos-for-data" aria-label="Permalink to &quot;SLOs for data&quot;">​</a></h2><p>Pipelines are products; products have contracts. The three SLO dimensions:</p><table tabindex="0"><thead><tr><th>SLO</th><th>Question</th><th>Typical measurement</th></tr></thead><tbody><tr><td><strong>Freshness</strong></td><td>How stale is the data?</td><td><code>max(event_time)</code> vs now, or last-partition-completed lag</td></tr><tr><td><strong>Completeness</strong></td><td>Did everything arrive?</td><td>Expected vs actual volume per window; reconciliation vs source counts</td></tr><tr><td><strong>Correctness</strong></td><td>Is the content right?</td><td>Contract validation pass rate, null/dup/outlier checks, canary queries</td></tr></tbody></table><ul><li><strong>SLA</strong> is the external promise (contract, penalty); <strong>SLO</strong> is the internal target (stricter, drives alerting); <strong>SLI</strong> is the measurement.</li><li>Error budgets apply to data too: a 99.9% freshness SLO means ~43 min/month of allowed staleness. Budget it, or you&#39;ll burn it silently.</li><li>SLOs need <em>consumers</em>: publish them to downstream teams — an SLO nobody reads is just monitoring.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Freshness SLOs are the most negotiated number in pipeline design — &quot;real-time&quot; costs 5-10× a 15-minute batch. Always ask &quot;what decision does staleness block?&quot; before accepting a freshness target.</p></div><h3 id="alerting-discipline" tabindex="-1">Alerting discipline <a class="header-anchor" href="#alerting-discipline" aria-label="Permalink to &quot;Alerting discipline&quot;">​</a></h3><p>Not every SLO breach deserves a page. Reserve pages for <em>user-impacting, actively-worsening</em> conditions — completeness failures, freshness burning error budget fast. Slow-burn degradations (low-rate quality failures, DLQ trickle) belong on dashboards and ticket queues. Alert fatigue is how real breaches get ignored.</p><h2 id="capacity-estimation-—-worked-example" tabindex="-1">Capacity estimation — worked example <a class="header-anchor" href="#capacity-estimation-—-worked-example" aria-label="Permalink to &quot;Capacity estimation — worked example&quot;">​</a></h2><p>The five-line model every interview (and real sizing exercise) runs on. Numbers are illustrative:</p><ol><li><strong>Rate</strong>: 50,000 events/sec peak, avg 500 B/event → <strong>25 MB/s ingest</strong>.</li><li><strong>Partitions</strong>: rule of thumb ~10 MB/s per Kafka partition (conservative) → <code>25/10 ≈ 3</code> — but size for <strong>peak × headroom (3×) and consumer parallelism</strong> → ~<strong>12-24 partitions</strong>, and round to a multiple that divides evenly across consumers.</li><li><strong>Storage</strong>: <code>25 MB/s × 86,400 s ≈ 2.2 TB/day</code>. With replication ×3 and 7-day retention → <code>2.2 × 3 × 7 ≈ 46 TB</code> hot in the log. Tiered/offloaded to lake: <code>2.2 × 365 ≈ 800 TB/yr</code> raw, ~3-5× less post-compression+columnar → ~<strong>200-300 TB/yr</strong>.</li><li><strong>Downstream</strong>: one Spark/Flink consumer group reading 25 MB/s is trivial; the cost driver is <em>recomputation</em> — a 30-day backfill reads 66 TB.</li><li><strong>Cost sketch</strong> (rough, order-of-magnitude): ~50 TB hot × ~$0.10-0.20/GB-mo ≈ <strong>$5-10k/mo</strong> log storage; lake at ~$0.02/GB-mo on ~250 TB ≈ <strong>$5k/mo</strong>; compute usually exceeds both — the real budget question is scan/compute, not storage.</li></ol><div class="info custom-block"><p class="custom-block-title">ℹ️</p><p>The interview skill isn&#39;t the arithmetic — it&#39;s narrating <em>which</em> number drives the design: here, retention × replication (46 TB log) and the recompute cost of backfills, not the ingest rate.</p></div><h2 id="failure-mode-→-mitigation-cheat-sheet" tabindex="-1">Failure-mode → mitigation cheat sheet <a class="header-anchor" href="#failure-mode-→-mitigation-cheat-sheet" aria-label="Permalink to &quot;Failure-mode → mitigation cheat sheet&quot;">​</a></h2><p>The whole chapter in one table — when an interviewer describes a symptom, name the pattern:</p><table tabindex="0"><thead><tr><th>Failure</th><th>Mitigation pattern</th></tr></thead><tbody><tr><td>Retried write duplicates a record</td><td>Idempotency key / natural-key upsert / partition overwrite</td></tr><tr><td>Lost event between DB write and message send</td><td>Transactional outbox + CDC relay</td></tr><tr><td>Consumer outage causes data loss</td><td>Durable log with retention &gt; worst-case recovery time</td></tr><tr><td>Poison record kills the whole consumer</td><td>Bounded retries → DLQ with payload + metadata + replay path</td></tr><tr><td>Producer deploys a field consumers can&#39;t parse</td><td>Schema registry compatibility check in CI; contract validation at ingest</td></tr><tr><td>Downstream table is wrong; fix needs rerun</td><td>Immutable raw layer + per-layer checkpoints + blue-green backfill</td></tr><tr><td>Bad data published, then corrected in place</td><td>Blue-green: rebuild alongside, atomic swap, keep old until verified</td></tr><tr><td>Dashboard numbers silently stale</td><td>Freshness/completeness/correctness SLIs with alerting, not just job status</td></tr><tr><td>Sync retry storm deepens an outage</td><td>Exponential backoff + jitter + retry budget + global deadline</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Notice what is absent: tool names. Every mitigation above works on Kafka or Kinesis, Flink or Spark, Airflow or Dagster. In design interviews, answering with the <em>pattern</em> and mentioning the tool parenthetically is what reads as senior.</p></div><h2 id="🧠-quiz" tabindex="-1">🧠 Quiz <a class="header-anchor" href="#🧠-quiz" aria-label="Permalink to &quot;🧠 Quiz&quot;">​</a></h2>',26)),s(u,{questions:[{q:"Why is exactly-once delivery impossible, and what do systems actually guarantee?",options:["It is possible with Kafka EOS","Two Generals Problem — no protocol guarantees delivery plus ack; systems offer at-least-once plus idempotent sinks for effective-once","Only batch systems can achieve it","Network reliability prevents it entirely"],correct:1,explain:"You cannot guarantee a message is both delivered and acknowledged over an unreliable network. What exists is effective-once: at-least-once transport plus dedupe/idempotent writes at the sink. Framework exactly-once (Kafka EOS, Flink) ends at the last framework-managed write."},{q:"Your consumer retries a timed-out write. What makes this safe?",options:["Exactly-once checkpointing in Flink","At-least-once delivery semantics","The message has a unique offset","An idempotency key or natural-key upsert at the sink so the retry dedupes to one write"],correct:3,explain:"Retry safety lives at the sink: a client-supplied idempotency key or a natural-key upsert (MERGE / ON CONFLICT) makes the second attempt a no-op. Framework exactly-once does not extend to external sinks."},{q:"A stream consumer falls behind but Kafka retains 7 days. What is backpressure doing here?",options:["The durable log buffers the backlog — the consumer drains at its own rate; data loss only if lag exceeds retention","Dropping old events to catch up","Rejecting new producer requests","Slowing producers via TCP"],correct:0,explain:"The durable log IS the backpressure mechanism: producers are unaffected, consumers drain at their own pace. Lag becomes loss only when retention expires. Load shedding/edge rejection is the alternative when there is no durable buffer."},{q:"A record poisons the consumer after 5 retries. The right DLQ design stores what?",options:["A pointer to the Kafka offset only","Just the error code","Nothing — dead-lettering is for notification only","The original payload plus error, attempt count, and source offset — and a replay path after the fix"],correct:3,explain:"A DLQ entry without the payload and provenance (offset, error, attempts) cannot be replayed or diagnosed. And a DLQ you cannot re-drive after the fix is a trash can: alerting on DLQ volume plus a replay path are the point."},{q:"You need consumers and producers to upgrade independently, in any order. Which schema compatibility and which change pattern?",options:["Forward — remove unused fields","Backward — add required fields","Full — only add optional fields with defaults, never remove or rename","None — schemas do not constrain upgrades"],correct:2,explain:"Full compatibility allows either side to upgrade first. The only change pattern that is safe under both backward and forward rules is adding optional fields with defaults; removes, renames, and type changes require coordination."},{q:"Sizing: 50k events/sec × 500B = 25 MB/s. With replication 3 and 7-day retention, hot log storage is roughly?",options:["800 TB","46 TB","15 GB","2 TB"],correct:1,explain:"25 MB/s × 86,400s ≈ 2.2 TB/day; ×3 replication ×7 days ≈ 46 TB in the log. The 800 TB figure is yearly raw lake storage before compression — the numbers answer different questions, which is the point of the estimation exercise."}]}),e[9]||(e[9]=i('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://builder.aws.com/content/3Ev0BENTyBr0XxzRk5FDZzgNYos/making-retries-safe-with-idempotent-apis" target="_blank" rel="noreferrer">Making retries safe with idempotent APIs — AWS Builders&#39; Library</a> — the canonical idempotency writeup.</li><li><a href="https://docs.confluent.io/platform/current/schema-registry/fundamentals/schema-evolution.html" target="_blank" rel="noreferrer">Confluent — Schema Evolution and Compatibility</a> — the compatibility rules table, authoritative.</li><li><a href="https://kafka.apache.org/documentation/#semantics" target="_blank" rel="noreferrer">Kafka design docs — exactly-once semantics</a> — what EOS actually covers and where it stops.</li><li><a href="https://nightlies.apache.org/flink/flink-docs-stable/docs/dev/datastream/fault-tolerance/checkpointing/" target="_blank" rel="noreferrer">Flink checkpointing &amp; fault tolerance docs</a> — checkpoint mechanics behind &quot;exactly-once.&quot;</li><li><a href="https://engineering.linkedin.com/distributed-systems/log-what-every-software-engineer-should-know-about-real-time-datas-unifying" target="_blank" rel="noreferrer">The Log — Jay Kreps</a> — why the durable log is the backbone of these architectures.</li><li><a href="https://sre.google/sre-book/service-level-objectives/" target="_blank" rel="noreferrer">Google SRE book — Service Level Objectives</a> — SLI/SLO/SLA framing that data SLOs borrow directly.</li><li><a href="https://docs.aws.amazon.com/wellarchitected/latest/framework/rel_prevent_interaction_failure_idempotent.html" target="_blank" rel="noreferrer">AWS Well-Architected — reliability pillar</a> — make mutating operations idempotent, retries, backoff.</li></ul>',2))])}const T=h(m,[["render",g]]);export{A as __pageData,T as default};
